products.push(...GoodfindCatalog.catalog);
const compareIds=new Set();
const key='goodfind-v1'; let state={favorites:[],collections:[],list:[],savedLists:[],outfit:[],preferences:{priority:'recommended',interests:[]}};try{const s=JSON.parse(localStorage.getItem(key));if(s&&typeof s==='object')state={...state,...s,preferences:{...state.preferences,...s.preferences}}}catch(e){} let category='All',query='',collection='all';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){toast('Could not save on this device. Check browser storage settings.')}}
let timer;function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3000)}
function shopUrl(q){return 'https://www.google.com/search?tbm=shop&q='+encodeURIComponent(q)}
function openShop(q){if(!q.trim()){toast('Enter something to search for first.');return}window.open(shopUrl(q),'_blank','noopener,noreferrer')}
function card(p){const saved=state.favorites.includes(p.id);return `<article class="product"><div class="image"><img src="${p.img}" alt="Illustrative image for ${esc(p.title)}" loading="lazy"><span class="badge">${esc(p.badge)}</span><button class="heart ${saved?'on':''}" data-fav="${p.id}" aria-label="${saved?'Remove':'Save'} ${esc(p.title)}" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><p class="category">${esc(p.store||'Sample store')} · ${esc(p.category)} · SAMPLE</p><h3>${esc(p.title)}</h3><p class="detail">${esc(p.detail)}</p><span class="price">$${p.price} <small>sample</small></span><span class="rating">${p.rating ? `★ ${p.rating} (${p.reviews} sample)` : "Reviews unavailable"}</span><div class="product-actions"><button data-detail="${p.id}">Details & compare</button><button data-add-outfit="${p.id}">Add to look</button><button data-file="${p.id}">Add to collection</button><button data-compare="${p.id}" aria-pressed="${compareIds.has(p.id)}">${compareIds.has(p.id)?"Remove from compare":"Compare"}</button>${p.link?`<a href="${esc(p.link)}" target="_blank" rel="noopener noreferrer">Search ${esc(p.store)} ↗</a>`:""}</div></article>`}
function renderProducts(){let arr=GoodfindCatalog.search(products,query).filter(p=>(category==='All'||(category==='Materials'?p.tags.includes('linen'):p.category===category))&&($('#store-filter').value==='all'||p.store===$('#store-filter').value));let sort=$('#sort').value;if(sort==='price')arr.sort((a,b)=>a.price-b.price);if(sort==='delivery')arr.sort((a,b)=>(a.delivery??Infinity)-(b.delivery??Infinity));if(sort==='rating')arr.sort((a,b)=>(b.rating??-1)-(a.rating??-1));if(sort==='recommended'&&!query){const interests=state.preferences.interests;arr.sort((a,b)=>Number(interests.includes(b.category))-Number(interests.includes(a.category)))}$('#products').innerHTML=arr.map(card).join('');$('#empty').hidden=!!arr.length;$('#results-label').textContent=`${arr.length} illustrative ${arr.length===1?'find':'finds'}${query?' for “'+query+'”':''}`;$('#online-empty').href=shopUrl(query||category);$('#compare-selected').textContent=`Compare selected (${compareIds.size})`}
function renderSaved(){const c=state.collections.find(x=>x.id===collection);if(collection!=='all'&&!c)collection='all';const ids=collection==='all'?state.favorites:(c?.items||[]);$('#saved-count').textContent=state.favorites.length?'('+state.favorites.length+')':'';$('#collection-list').innerHTML=`<button class="collection ${collection==='all'?'active':''}" data-collection="all">All favorites (${state.favorites.length})</button>`+state.collections.map(x=>`<button class="collection ${collection===x.id?'active':''}" data-collection="${x.id}">${esc(x.name)} (${x.items.length})</button>`).join('');$('#collection-title').textContent=c?.name||'All favorites';$('#rename-collection').hidden=collection==='all';$('#delete-collection').hidden=collection==='all';const saved=products.filter(p=>ids.includes(p.id));const byStore=$('#saved-view').value==='stores';$('#saved-products').classList.toggle('by-store',byStore);$('#saved-products').innerHTML=byStore?Object.entries(GoodfindCatalog.groupByStore(saved)).map(([store,items])=>`<section class="store-group"><h4>${esc(store)} · ${items.length} ${items.length===1?'item':'items'}</h4><p class="muted">Sample subtotal: $${items.reduce((n,p)=>n+p.price,0).toFixed(2)} · shipping and tax unknown</p><div class="saved-grid">${items.map(card).join('')}</div></section>`).join(''):saved.map(card).join('');$('#saved-empty').hidden=saved.length>0}
function renderList(){const selected=$('#saved-lists').value;$('#saved-lists').innerHTML='<option value="">Select a list</option>'+(state.savedLists||[]).map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');$('#saved-lists').value=selected;$('#list-items').innerHTML=state.list.map(x=>`<li><input type="checkbox" data-check="${x.id}" aria-label="Mark ${esc(x.text)} complete" ${x.done?'checked':''}><span ${x.done?'style="text-decoration:line-through"':''}>${esc(x.text)}</span><button data-list-search="${x.id}">Find matches</button><button data-amazon-search="${x.id}">Amazon</button><button data-remove-list="${x.id}" aria-label="Remove ${esc(x.text)}">Remove</button></li>`).join('');$('#list-empty').hidden=!!state.list.length}
function renderOutfit(){$('#outfit-select').innerHTML=products.filter(p=>['Fashion','Accessories'].includes(p.category)&&!state.outfit.includes(p.id)).map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');$('#outfit-items').innerHTML=state.outfit.map(id=>products.find(p=>p.id===id)).filter(Boolean).map(p=>`<span class="outfit-chip">${esc(p.title)} <button data-remove-outfit="${p.id}" aria-label="Remove ${esc(p.title)}">×</button></span>`).join('')||'<p class="muted">Your look starts here.</p>';$('#add-outfit').disabled=!$('#outfit-select').value}
function render(){renderProducts();renderSaved();renderList();renderOutfit()}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML='<div class="dialog-body">'+html+'</div>';$('#dialog').showModal()}
function newId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function details(p){dialog(p.title,`<p><strong>Illustrative product</strong> · ${esc(p.detail)}</p><p>Sample price: $${p.price} · Delivery: ${p.delivery?p.delivery+' sample days':'unknown'} · Rating: ${p.rating?p.rating+'/5 ('+p.reviews+' sample reviews)':'unavailable'}.</p><p>These figures are examples, not real retailer offers. Live price, delivery and review comparisons will need a connected product provider.</p><button class="dark-btn" id="find-similar">Find similar in Goodfind</button><button class="outline" id="find-live">Search Google Shopping</button><button class="outline" id="save-detail">${state.favorites.includes(p.id)?'Remove from favorites':'Save to favorites'}</button>`);$('#find-similar').onclick=()=>{const term=p.tags.slice(0,3).join(' ');$('#dialog').close();$('#query').value=term;$('#search-form').requestSubmit()};$('#find-live').onclick=()=>openShop(p.title);$('#save-detail').onclick=()=>{toggleFav(p.id);$('#dialog').close()}}
function toggleFav(id){if(state.favorites.includes(id)){state.favorites=state.favorites.filter(x=>x!==id);state.collections.forEach(c=>c.items=c.items.filter(x=>x!==id));toast('Removed from favorites')}else{state.favorites.push(id);toast('Saved to favorites')}save();render()}
function preferences(){const cats=['Fashion','Beauty','Home','Accessories'];dialog('Make it yours',`<p>Your preferences help prioritize the demo feed and are stored locally on this computer.</p><label for="priority">What matters most?</label><select id="priority"><option value="recommended">A little of everything</option><option value="price">Lower prices</option><option value="delivery">Faster delivery</option><option value="rating">Higher ratings</option></select><fieldset><legend>What are you into?</legend>${cats.map(c=>`<label><input type="checkbox" class="interest" value="${c}" ${state.preferences.interests.includes(c)?'checked':''}> ${c==='Home'?'Home & living':c}</label>`).join('')}</fieldset><p>Lists, favorites and outfits are saved in this browser. The demo preferences profile is saved on this computer. No sign-in or cross-device sync is active.</p><button id="save-prefs" class="dark-btn">Save preferences</button><button id="clear-data" class="outline">Clear my data</button>`);$('#priority').value=state.preferences.priority;$('#save-prefs').onclick=async()=>{state.preferences={priority:$('#priority').value,interests:[...document.querySelectorAll('.interest:checked')].map(x=>x.value)};$('#sort').value=state.preferences.priority;save();render();try{await saveProfile(state.preferences);$('#dialog').close();toast('Preferences saved to your local profile')}catch(e){$('#dialog').close();toast('Saved in browser; local profile unavailable')}};$('#clear-data').onclick=async()=>{if(confirm('Clear your local profile, list, favorites, collections and outfits?')){try{const response=await fetch('/api/profile',{method:'DELETE'});if(!response.ok)throw new Error();localStorage.removeItem(key);location.reload()}catch(e){toast('Could not clear the local profile. Start the Goodfind server and try again.')}}}}
function help(){dialog('How can we help?',`<p>Goodfind is an early preview. Products and orders are not connected, so purchases and order issues remain with the retailer you bought from.</p><p>A support address hasn’t been configured yet, so feedback cannot be submitted through this preview.</p><p><strong>Need help with an order?</strong> Contact the retailer directly using your order confirmation.</p><p>Questions about this preview? Share them with the person who sent it to you.</p>`)}
$('#search-form').onsubmit=e=>{e.preventDefault();query=$('#query').value.trim();category='All';document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.category==='All'));renderProducts();document.querySelector('.discovery').scrollIntoView();if(query)searchWeb(query)};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.query;$('#search-form').requestSubmit()});$('#filters').onclick=e=>{let b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;document.querySelectorAll('#filters button').forEach(x=>x.classList.toggle('active',x===b));renderProducts()};$('#sort').onchange=renderProducts;$('#online-search').onclick=()=>searchWeb(query||$('#query').value);$('#list-form').onsubmit=e=>{e.preventDefault();const lines=$('#list-input').value.split(/\n/).map(x=>x.trim()).filter(Boolean).slice(0,30);if(!lines.length){toast('Add at least one item first.');return}lines.forEach(text=>state.list.push({id:newId(),text:text.slice(0,120),done:false}));$('#list-input').value='';save();renderList();toast('Added to your list')};$('#list-search').onclick=()=>{const item=state.list.find(x=>!x.done);if(!item){toast('Add an unchecked item first.');return}if($('#list-dialog').open)$('#list-dialog').close();$('#query').value=item.text;$('#search-form').requestSubmit()};$('#create-collection').onclick=()=>{const name=prompt('Name your collection:')?.trim();if(!name)return;if(name.length>60){toast('Use a name under 60 characters.');return}const c={id:newId(),name,items:[]};state.collections.push(c);collection=c.id;save();renderSaved()};$('#rename-collection').onclick=()=>{const c=state.collections.find(x=>x.id===collection),name=prompt('Rename collection:',c.name)?.trim();if(name&&name.length<=60){c.name=name;save();renderSaved()}};$('#delete-collection').onclick=()=>{const c=state.collections.find(x=>x.id===collection);if(confirm(`Delete “${c.name}”? Your favorites will stay saved.`)){state.collections=state.collections.filter(x=>x.id!==collection);collection='all';save();renderSaved()}};$('#add-outfit').onclick=()=>{let id=$('#outfit-select').value;if(id&&!state.outfit.includes(id)){state.outfit.push(id);save();renderOutfit()}};$('#start-outfit').onclick=()=>$('#outfit-select').focus();$('#save-outfit').onclick=()=>{if(!state.outfit.length){toast('Add a piece to your look first.');return}dialog('Save your look',`<p>Save these pieces together in your collections on this device.</p><label for="look-name">Collection name</label><input id="look-name" type="text" maxlength="60" placeholder="e.g. Night out"><button id="confirm-look" class="dark-btn">Save look</button><p id="look-error" role="alert"></p>`);$('#confirm-look').onclick=()=>{const name=$('#look-name').value.trim();if(!name){$('#look-error').textContent='Enter a collection name.';return}state.outfit.forEach(id=>{if(!state.favorites.includes(id))state.favorites.push(id)});const c={id:newId(),name,items:[...state.outfit]};state.collections.push(c);collection=c.id;save();render();$('#dialog').close();toast('Look saved to collections')}};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.file){const id=el.dataset.file;if(!state.collections.length){toast('Create a collection in Saved first.');return}dialog('Add to collection',`<label for="file-select">Choose a collection</label><select id="file-select">${state.collections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button id="file-save" class="dark-btn">Save to collection</button>`);$('#file-save').onclick=()=>{const c=state.collections.find(x=>x.id===$('#file-select').value);if(!c.items.includes(id))c.items.push(id);if(!state.favorites.includes(id))state.favorites.push(id);save();render();$('#dialog').close();toast('Added to collection')}}if(el.dataset.compare){const id=el.dataset.compare;if(compareIds.has(id))compareIds.delete(id);else if(compareIds.size<3)compareIds.add(id);else toast('Choose up to three items to compare');render()}if(el.dataset.fav)toggleFav(el.dataset.fav);if(el.dataset.detail)details(products.find(p=>p.id===el.dataset.detail));if(el.dataset.collection){collection=el.dataset.collection;renderSaved()}if(el.dataset.removeList){state.list=state.list.filter(x=>x.id!==el.dataset.removeList);save();renderList()}if(el.dataset.listSearch){let x=state.list.find(x=>x.id===el.dataset.listSearch);if($('#list-dialog').open)$('#list-dialog').close();$('#query').value=x.text;$('#search-form').requestSubmit()}if(el.dataset.amazonSearch){let x=state.list.find(x=>x.id===el.dataset.amazonSearch);window.open('https://www.amazon.com/s?k='+encodeURIComponent(x.text),'_blank','noopener,noreferrer')}if(el.dataset.removeOutfit){state.outfit=state.outfit.filter(x=>x!==el.dataset.removeOutfit);save();renderOutfit()}if(el.dataset.addOutfit){if(!state.outfit.includes(el.dataset.addOutfit)){state.outfit.push(el.dataset.addOutfit);save();renderOutfit()}toast('Added to your look')}});document.addEventListener('change',e=>{if(e.target.dataset.check){let x=state.list.find(x=>x.id===e.target.dataset.check);if(x){x.done=e.target.checked;save();renderList()}}});$('#pref-open').onclick=preferences;$('#privacy-open').onclick=preferences;$('#help-open').onclick=help;$('#bottom-help').onclick=help;$('#dialog-close').onclick=()=>$('#dialog').close();$('#about-demo').onclick=()=>dialog('About this preview','<p>This early version uses an illustrative catalog. Product names, prices, ratings and delivery estimates are examples and are not verified retailer offers.</p><p>Your list, favorites, collections, outfit and preferences are saved only in this browser. Live search can display results when a search provider is configured.</p><p>Accounts, syncing, orders, checkout, loyalty cards, affiliate tracking and cross-platform reviews are not connected yet.</p>');$('#sort').value=state.preferences.priority;$('#store-filter').innerHTML+=[...new Set(products.map(p=>p.store).filter(Boolean))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('#store-filter').onchange=renderProducts;$('#saved-view').onchange=renderSaved;$('#compare-selected').onclick=()=>{const selected=products.filter(p=>compareIds.has(p.id));if(selected.length<2){toast('Choose two or three items to compare');return}dialog('Compare sample finds',`<p>Illustrative data only. Shipping, tax, stock and live prices are not verified.</p><div class="compare-grid">${selected.map(p=>`<div><strong>${esc(p.title)}</strong><p>${esc(p.store||'Sample store')} · $${p.price} sample</p><p>${esc(p.detail)}</p><p>Delivery: ${p.delivery?p.delivery+' sample days':'unknown'}</p></div>`).join('')}</div>`)};render();

$('#load-sara').onclick=()=>{if(!confirm('Add Sara’s five example items to your current list and apply her sample preferences? Your existing items will stay.'))return;const entries=['Cropped fitted leather jacket size small','Grace & Stella energizing eye pads','Black cotton fitted top size small','Set of black warm boot socks','Black platform pumps size 7'];for(const text of entries){if(!state.list.some(x=>x.text.toLowerCase()===text.toLowerCase()))state.list.push({id:newId(),text,done:false})}state.preferences={...state.preferences,interests:['Fashion','Beauty','Accessories'],sampleProfile:{name:'Sara',clothingSize:'S',shoeSize:'7',occasions:['going out','cocktail wear'],interests:['cosmetics','trendy'],materials:['cotton','modal','leather','rayon','faux leather'],ingredientPreference:'non-toxic: criteria not specified'}};save();render();toast('Sara’s example is ready')};

// Shopping lists are stored locally until user accounts are connected.
const listCard=$('#list-card'),listParent=listCard.parentNode,listNext=listCard.nextSibling;
$('#expand-list').onclick=()=>{const d=$('#list-dialog');$('#list-dialog-content').appendChild(listCard);$('#expand-list').hidden=true;d.showModal()};
$('#list-dialog-close').onclick=()=>$('#list-dialog').close();
$('#list-dialog').addEventListener('close',()=>{listParent.insertBefore(listCard,listNext);$('#expand-list').hidden=false});
$('#save-list').onclick=()=>{if(!state.list.length){toast('Add items before saving your list');return}let name=prompt('Name this shopping list:')?.trim().slice(0,60);if(!name)return;state.savedLists??=[];state.savedLists.push({id:newId(),name,items:state.list.map(x=>({...x}))});save();renderList();toast('List saved on this device')};
$('#load-list').onclick=()=>{const l=(state.savedLists||[]).find(x=>x.id===$('#saved-lists').value);if(!l){toast('Choose a saved list first');return}if(state.list.length&&!confirm('Replace the current list with this saved list? Save your current list first if you want to keep it.'))return;state.list=l.items.map(x=>({...x}));save();renderList();toast('List opened')};
$('#delete-list').onclick=()=>{const id=$('#saved-lists').value;if(!id){toast('Choose a saved list first');return}if(confirm('Delete this saved list?')){state.savedLists=state.savedLists.filter(x=>x.id!==id);save();renderList();toast('Saved list deleted')}};
$('#preview-outfit').onclick=()=>{const items=state.outfit.map(id=>products.find(p=>p.id===id)).filter(Boolean);if(!items.length){toast('Add a piece to preview your look');return}dialog('Your look',`<p>Items shown together for inspiration. Sample images and listings are illustrative.</p><div class="look-preview">${items.map(p=>`<figure><img src="${esc(p.img)}" alt="${esc(p.title)}" loading="lazy"><figcaption>${esc(p.title)}</figcaption></figure>`).join('')}</div>`)};
async function searchWeb(q){q=String(q||'').trim();if(!q){toast('Enter something to search for first');return}const section=$('#web-results'),status=$('#web-status'),grid=$('#web-grid');section.hidden=false;grid.innerHTML='';status.textContent='Searching the web…';try{const response=await fetch('/api/search?q='+encodeURIComponent(q));const data=await response.json();if(!response.ok)throw new Error(data.error||'Search is unavailable.');if(!Array.isArray(data.results)||!data.results.length){status.textContent='No results found. Try another search.';return}status.textContent='Web results · Prices and availability may change; confirm with the retailer.';grid.innerHTML=data.results.map(p=>`<article class="product"><div class="image">${p.image?`<img src="${esc(p.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}</div><p class="category">${esc(p.store||'Retailer')}</p><h3>${esc(p.title)}</h3><p>${esc(p.price||'Price unavailable')}</p><p class="detail">${esc(p.delivery||'Delivery details unavailable')}</p>${p.link?`<a href="${esc(p.link)}" target="_blank" rel="noopener noreferrer">Open offer</a>`:'<span class="muted">Retailer link unavailable</span>'}</article>`).join('')}catch(e){status.textContent=e.message||'Could not load web results. Please try again.'}}

async function saveProfile(preferences){const res=await fetch('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({priority:preferences.priority,interests:preferences.interests})});if(!res.ok)throw new Error('Profile unavailable');}
async function loadProfile(){try{const res=await fetch('/api/profile');if(!res.ok)return;const data=await res.json();if(data.profile){state.preferences={...state.preferences,...data.profile};$('#sort').value=state.preferences.priority;save();render()}}catch(e){/* retain browser preferences when server unavailable */}}
loadProfile();
